css:
.fx-ring{width:min(940px,100%);text-align:center;display:grid;gap:2.2em;justify-items:center}
.fx-ring h2{font-size:clamp(1.9em,4.4vw,2.8em);max-width:18ch}
.fx-ring .row{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1.2em;width:100%}
.fx-ring .r{display:grid;justify-items:center;gap:.9em;padding:1.5em .8em;border:1px solid var(--border);border-radius:var(--radius);background:color-mix(in srgb,var(--surface) 94%,var(--text))}
.fx-ring .rg{position:relative;width:min(8.5em,100%);aspect-ratio:1}
.fx-ring .rg svg{width:100%;height:100%;transform:rotate(-90deg);overflow:visible}
.fx-ring .rg circle{fill:none;stroke-width:7}
.fx-ring .rg .tk{stroke:color-mix(in srgb,var(--text) 10%,transparent)}
.fx-ring .rg .bar{stroke:var(--c,var(--primary));stroke-linecap:round;stroke-dasharray:100;stroke-dashoffset:calc(100 - var(--p));transition:stroke-dashoffset calc(1.5s/var(--speed)) cubic-bezier(.3,.7,.2,1)}
.fx-ring .pre .rg .bar{stroke-dashoffset:100;transition:none}
.fx-ring .r:nth-child(2) .bar{--c:var(--accent)}.fx-ring .r:nth-child(4) .bar{--c:color-mix(in srgb,var(--primary) 55%,var(--accent))}
.fx-ring .rg .v{position:absolute;inset:0;display:grid;place-items:center;font:600 clamp(1.5em,3.2vw,2em) var(--font-heading);font-variant-numeric:tabular-nums}
.fx-ring .rg .v sup{font-size:.5em;opacity:.6;top:-.5em;margin-left:1px}
.fx-ring .l{font-size:.9em;opacity:.7}
.fx-ring small{opacity:.5}
@media(max-width:760px){.fx-ring .row{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(prefers-reduced-motion:reduce){.fx-ring .rg .bar{transition:none}}

js:
(function(){var root=document.querySelector('.fx-ring');function sp(){return parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--speed'))||1}
var reduce=matchMedia('(prefers-reduced-motion:reduce)').matches;
function run(){root.classList.add('pre');root.querySelectorAll('[data-to]').forEach(function(e){e.textContent=0});void root.offsetWidth;
if(reduce){root.classList.remove('pre');root.querySelectorAll('[data-to]').forEach(function(e){e.textContent=e.dataset.to});return}
requestAnimationFrame(function(){root.classList.remove('pre');root.querySelectorAll('[data-to]').forEach(function(el){var to=+el.dataset.to,t0=null,d=1500/sp();function f(t){if(!t0)t0=t;var p=Math.min((t-t0)/d,1),e=1-Math.pow(1-p,3);el.textContent=Math.round(to*e);if(p<1)requestAnimationFrame(f)}requestAnimationFrame(f)})})}
if('IntersectionObserver' in window){root.classList.add('pre');var io=new IntersectionObserver(function(es){if(es[0].isIntersecting){run();io.disconnect()}},{threshold:.3});io.observe(root)}
root.addEventListener('click',run)})();
